"""v10 COMPONENTS template: COMPONENTS.v9src.md + v10 edits -> COMPONENTS.md."""
import os
HERE = os.path.dirname(os.path.abspath(__file__))
s = open(os.path.join(HERE, 'COMPONENTS.v9src.md')).read()


def rep(old, new, cnt=1):
    global s
    assert s.count(old) == cnt, (s.count(old), old[:100])
    s = s.replace(old, new)


rep('# Utility Plane v9 для Unity — описание модели и карта компонентов', '# Utility Plane v10 для Unity — описание модели и карта компонентов')
rep('''В Unity v9 не запускался. Всё ниже описывает файлы:''', '''В Unity v10 не запускался. v10 — оптимизация v9: состав, назначение и имена частей те же, меньше треугольников, текстуры интерьера 1024 px (шкалы 2048), тени крупных частей от упрощённых копий (контракт, раздел 17). Всё ниже описывает файлы:''')
rep('''атласы интерьера Cockpit, Interior, Floor, Seats (BaseColor, Normal, MaskMap, 4K) и v9 `T_Fittings` (2K); атлас шкал и экранов,''',
    '''атласы интерьера Cockpit, Interior, Floor, Seats и v9 `T_Fittings` (BaseColor, Normal, MaskMap; v10: 1024², было 4K и 2K); атлас шкал и экранов (v10: 2048²),''')
rep('''- v8: у `Body`, дверей, колёс, хвостового колеса, кока и стоек шасси есть дочерние LOD-меши `<часть>_LOD1` / `_LOD2`, в кабине — у `Cockpit_Static` и рогов штурвалов (`Yoke_*_Roll_LOD1`); они едут вместе с частью. Rig ими не управляет, только ставит экземпляр подсветки `M_Gauges` и на них (контракт, раздел 8.1).''',
    '''- v8: у `Body`, дверей, колёс, хвостового колеса, кока и стоек шасси есть дочерние LOD-меши `<часть>_LOD1` / `_LOD2`, в кабине — у `Cockpit_Static` и рогов штурвалов (`Yoke_*_Roll_LOD1`); они едут вместе с частью. Rig ими не управляет, только ставит экземпляр подсветки `M_Gauges` и на них (контракт, раздел 8.1).
- v10: у `Cockpit_Static`, `Cabin_Fittings`, `Wheel_L/R`, `TailWheel` есть дочерние теневые копии `<часть>_Shadow`: в цвет не рисуются, только тень в LOD0 (сама часть тени не отбрасывает). Код, который прячет или подсвечивает рендереры самолёта, должен прятать их вместе с частью и не подсвечивать.''')
rep('''Сделано в v9: экстерьер PS1/PSX,''', '''Сделано в v10: оптимизация без изменения вида — около {V10_LOD0_K} тыс. треугольников вблизи вместо {V10_LOD0_K9}, невидимые грани кабины удалены, новые LOD, теневые копии, текстуры интерьера 1024 px (шкалы 2048), около {V10_VRAM} МБ видеопамяти текстур вместо {V10_VRAM9}, FBX без Read/Write, Rig без лишних записей (контракт, раздел 17).

Сделано в v9: экстерьер PS1/PSX,''')
rep('''| V9-4 | Экстерьер PS1/PSX | **есть** (v9), интерьер прежний по решению пользователя |''',
    '''| V9-4 | Экстерьер PS1/PSX | **есть** (v9), интерьер прежний по решению пользователя |
| V10 | Оптимизация модели | **есть** (v10): решение пользователя — интерьер 1024 px, геометрия умеренно, без видимой разницы |''')
open(os.path.join(HERE, 'COMPONENTS.md'), 'w').write(s)
print('components template v10', len(s))
